8	
9		"example.com/tally/internal/auth"
10		"example.com/tally/internal/billing"
11		"example.com/tally/internal/money"
12		"example.com/tally/internal/payments"
13		"example.com/tally/internal/store"
14	)
15	
16	// invoiceView is an invoice as the API shows it: with its totals, a one-line description and its customer.
17	type invoiceView struct {
18		store.Invoice
19		billing.Totals
20		TotalFormatted string       `json:"total_formatted"`
21		Description    string       `json:"description"`
22		Customer       *customerRef `json:"customer"`
23	}
24	
25	// customerRef is the customer shown on an invoice; null when the customer was deleted.
26	type customerRef struct {
27		ID    string `json:"id"`
28		Name  string `json:"name"`
29		Email string `json:"email"`
30	}
31	
32	func newInvoiceView(inv store.Invoice, c *store.Customer) invoiceView {
33		t := billing.Compute(inv)
34		v := invoiceView{Invoice: inv, Totals: t, TotalFormatted: money.Format(t.Total, inv.Currency), Description: describe(inv.Lines)}
35		if c != nil {
36			v.Customer = &customerRef{ID: c.ID, Name: c.Name, Email: c.Email}
37		}
38		return v
39	}
40	
41	// describe is the invoice's first line, and how many more there are.
42	func describe(lines []store.Line) string {
43		d := lines[0].Description
44		if len(lines) > 1 {
45			d += fmt.Sprintf(" and %d more", len(lines)-1)
46		}
47		return d
48	}
49	
50	func (s *Server) viewInvoice(inv store.Invoice) invoiceView {
51		if c, ok := s.store.Customer(inv.OrgID, inv.CustomerID); ok {
52			return newInvoiceView(inv, &c)
53		}
54		return newInvoiceView(inv, nil)
55	}
56	
57	func findCustomer(cs []store.Customer, id string) *store.Customer {
58		for i := range cs {
59			if cs[i].ID == id {
60				return &cs[i]
61			}
62		}
63		return nil
64	}
65	
66	func invoiceViewKey(v invoiceView) cursor { return cursor{T: v.CreatedAt, ID: v.ID} }
67	
68	// listInvoices lists the organization's invoices, oldest first, optionally only those of ?customer_id=, ?subscription_id=
69	// or with ?status=.
70	func (s *Server) listInvoices(w http.ResponseWriter, r *http.Request, p auth.Principal) {
71		pg, ok := parsePage(w, r)
72		if !ok {
