package money

import (
	"errors"
	"testing"
)

func TestParseMajor(t *testing.T) {
	for _, c := range []struct {
		in   string
		cur  Currency
		want int64
	}{
		{"12.50", USD, 1250},
		{"12.5", USD, 1250},
		{"7", EUR, 700},
		{"0.99", GBP, 99},
		{" 1000.00 ", USD, 100000},
		{"1000", JPY, 1000},
		{"7", KWD, 7000},
		{"1.250", KWD, 1250},
		{"0.005", KWD, 5},
		{"0.001", KWD, 1},
	} {
		got, err := ParseMajor(c.in, c.cur)
		if err != nil || got != c.want {
			t.Errorf("ParseMajor(%q, %s) = %d, %v; want %d", c.in, c.cur, got, err, c.want)
		}
	}
	for _, c := range []struct {
		in  string
		cur Currency
	}{
		{"", USD},
		{"abc", USD},
		{"-1", USD},
		{"+1", USD},
		{"1 000", USD},
		{"1.", USD},
		{".5", USD},
		{"1.234", USD},
		{"1,000", USD},
		{"1.0", JPY},
		{"1000.", JPY},
		{"-1000", JPY},
		{"1.5", JPY},
		{"1.2345", KWD},
		{"1.0000", KWD},
		{"-7", KWD},
	} {
		if _, err := ParseMajor(c.in, c.cur); !errors.Is(err, ErrInvalidAmount) {
			t.Errorf("ParseMajor(%q, %s) = %v, want ErrInvalidAmount", c.in, c.cur, err)
		}
	}
	if _, err := ParseMajor("1", "XYZ"); !errors.Is(err, ErrInvalidAmount) {
		t.Errorf("unknown currency: %v", err)
	}
}

func TestMinorUnits(t *testing.T) {
	for c, want := range map[Currency]int{USD: 2, EUR: 2, GBP: 2, JPY: 0, KWD: 3} {
		if got := c.MinorUnits(); got != want {
			t.Errorf("%s.MinorUnits() = %d, want %d", c, got, want)
		}
	}
}

func TestFormat(t *testing.T) {
	for _, c := range []struct {
		amount int64
		cur    Currency
		want   string
	}{
		{1250, USD, "$12.50"},
		{123456789, USD, "$1,234,567.89"},
		{-99, EUR, "-€0.99"},
		{0, GBP, "£0.00"},
		{100000, GBP, "£1,000.00"},
		{99, EUR, "€0.99"},
		{1200, GBP, "£12.00"},
		{1000, JPY, "¥1,000"},
		{-5, JPY, "-¥5"},
		{123456789, JPY, "¥123,456,789"},
		{1250, KWD, "KWD 1.250"},
		{-5, KWD, "-KWD 0.005"},
	} {
		if got := Format(c.amount, c.cur); got != c.want {
			t.Errorf("Format(%d, %s) = %q, want %q", c.amount, c.cur, got, c.want)
		}
	}
}

func TestFormatMajor(t *testing.T) {
	for _, c := range []struct {
		amount int64
		cur    Currency
		want   string
	}{
		{1250, USD, "12.50"},
		{123456789, USD, "1234567.89"},
		{1000, JPY, "1000"},
		{1250, KWD, "1.250"},
		{5, KWD, "0.005"},
		{-5, KWD, "-0.005"},
	} {
		if got := FormatMajor(c.amount, c.cur); got != c.want {
			t.Errorf("FormatMajor(%d, %s) = %q, want %q", c.amount, c.cur, got, c.want)
		}
	}
}

func TestRounding(t *testing.T) {
	for _, c := range []struct {
		amount int64
		pct    int
		want   int64
	}{
		{1000, 15, 150},
		{999, 10, 100}, // 99.9
		{995, 10, 100}, // 99.5 rounds up
		{994, 10, 99},
